package com.bank.ledger.service;

import com.bank.ledger.model.RefNode;
import java.util.logging.Logger;

// Removes consecutive duplicates from sorted structures, in place.
public class LedgerDeduplicator {
    private static final Logger log = Logger.getLogger(LedgerDeduplicator.class.getName());

    // Sorted array: returns the count of unique elements kept at the front.
    public int removeDuplicates(int[] accounts) {
        if (accounts == null || accounts.length == 0) return 0;
        int slow = 0; // last unique index
        for (int fast = 1; fast < accounts.length; fast++) {
            if (accounts[fast] != accounts[slow]) {
                slow++;
                accounts[slow] = accounts[fast];
            }
        }
        int uniqueCount = slow + 1;
        log.info(() -> "Array unique count = " + uniqueCount);
        return uniqueCount;
    }

    // Sorted linked list: unlink consecutive duplicate nodes, return head.
    public RefNode removeDuplicates(RefNode head) {
        RefNode current = head;
        while (current != null && current.next != null) {
            if (current.next.ref == current.ref) {
                current.next = current.next.next; // skip the duplicate node
            } else {
                current = current.next;
            }
        }
        log.info("Linked list duplicates removed.");
        return head;
    }
}
