package com.bank.ledger;

import com.bank.ledger.model.RefNode;
import com.bank.ledger.service.LedgerDeduplicator;
import java.util.Arrays;
import java.util.logging.Logger;

public class DedupDemo {
    private static final Logger log = Logger.getLogger(DedupDemo.class.getName());

    public static void main(String[] args) {
        LedgerDeduplicator dedup = new LedgerDeduplicator();

        // Array case: sorted account numbers with repeats.
        int[] accounts = {101, 101, 102, 103, 103, 103, 104};
        int count = dedup.removeDuplicates(accounts);
        log.info(() -> "Unique accounts: "
                + Arrays.toString(Arrays.copyOf(accounts, count)));

        // Linked list case: sorted transaction references with repeats.
        RefNode head = build(new int[]{501, 501, 502, 503, 503});
        head = dedup.removeDuplicates(head);
        log.info(() -> "Unique refs: " + toText(head));
    }

    private static RefNode build(int[] refs) {
        RefNode dummy = new RefNode(-1);
        RefNode tail = dummy;
        for (int r : refs) { tail.next = new RefNode(r); tail = tail.next; }
        return dummy.next;
    }

    private static String toText(RefNode head) {
        StringBuilder sb = new StringBuilder("[");
        for (RefNode n = head; n != null; n = n.next) {
            sb.append(n.ref);
            if (n.next != null) sb.append(", ");
        }
        return sb.append("]").toString();
    }
}
